sys_variable_value.value:
(function execute(inputs, outputs) {
    // Asset tag: same VCARD convention as the rest of the app, checked for collisions.
    var tag = '';
    for (var i = 0; i < 5 && !tag; i++) {
        var candidate = 'VCARD' + (Math.floor(Math.random() * 900000) + 1);
        var chk = new GlideRecord('alm_asset');
        chk.addQuery('asset_tag', candidate);
        chk.setLimit(1);
        chk.query();
        if (!chk.hasNext()) tag = candidate;
    }
    if (!tag) tag = 'VCARD' + new GlideDateTime().getNumericValue();

    outputs.asset_tag = tag;
    outputs.assigned = new GlideDateTime().getValue();
})(inputs, outputs);

